1758	\begin{lemma}[Removing the $X$-point factor]
1759		\label{lem:claim-17-2}
1760		\notready
1761		% claim:17-2 in the paper; the original label is recorded here as a
1762		% comment for cross-reference fidelity. The source right-hand side
