1776			&\sum_{f_X,f_Z} \bra{\hat\psi}
1777			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1778			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)} \,
1779			\hat{M}^{(\mathrm{Point},X),x}_{f_X(x)}
1780			\big)_{\mathsf{B}\mathsf{A}''}
1781			\ket{\hat\psi} \\
1782			\approx_{m\,\delta_{\mathrm{Line}}^{1/2}}\
1783			\E_{(\ell,\ell_X,\ell_Z) \sim D}\
1784			\E_{(x,z,\alpha,\beta) \in \ell}
1785			&\sum_{f_X,f_Z} \bra{\hat\psi}
1786			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1787			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)}
1788			\big)_{\mathsf{B}\mathsf{A}''}
1789			\ket{\hat\psi}\,,
1790		\end{align*}
