1794	\begin{proof}
1795		\uses{lem:qld-comm-line-cons, lem:qld-sublines, lem:qld-xz-lines,
1796			lem:restricted-line-mixture-bounds, def:ith-restricted-line,
1797			def:expanded-line-measurement}
