1836		\uses{lem:qld-sublines, lem:qld-xz-lines, lem:qld-4-10,
1837			def:expanded-point-measurement, def:expanded-state}
1838		\[
1839			\E_{(\ell,\ell_X,\ell_Z) \sim D}\
1840			\E_{(x,z,\alpha,\beta) \in \ell}
1841			\sum_{f_X,f_Z} \bra{\hat\psi}
1842			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1843			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)}
1844			\big)_{\mathsf{B}\mathsf{A}''}
1845			\ket{\hat\psi}
1846			\ \approx_{\sqrt{m}\,(\delta_P^{1/4} + \delta_Q^{1/4} +
1847				\eps^{1/4})}\ 1\,.
1848		\]
1849	\end{lemma}
1850	\begin{proof}
1851		\uses{lem:restricted-line-mixture-bounds, lem:qld-sublines,
1852			lem:qld-xz-lines, lem:qld-4-10, lem:qld-comm-cons,
1853			def:ith-restricted-line}
1854		By Cauchy--Schwarz it suffices to bound the deficit
1855		$1 - \E \sum_b \bra{\hat\psi} T^{\ell_X,\ell_Z,z}_{b} \ot
1856		\hat{M}^{(\mathrm{Point},Z),z}_{b} \ket{\hat\psi}$,
1857		where
1858		$T^{\ell_X,\ell_Z,z}_{b}
1859		= \sum_{f_X} T^{\ell_X,\ell_Z}_{f_X,[\mathrm{eval}_z(\cdot)=b]}$.
1860		By Property~2 of Lemma~\ref{lem:qld-sublines}, the expectation can be
1861		rewritten over the mixture of product distributions
1862		$D_{\mathrm{v},i} \times D_{\mathrm{v},j}$ with $z$ uniformly random on
1863		$\ell_Z$, and, since
1864		$T^{\ell_X,\ell_Z,z}_{b}
1865		= \E_{x \in \ell_X} \sum_a
1866		T^{\ell_X,\ell_Z}
1867		_{[\mathrm{eval}_x(\cdot)=a,\ \mathrm{eval}_z(\cdot)=b]}$,
1868		one may additionally average over $x$ uniformly random on $\ell_X$. Up
1869		to error $m(\sqrt{\delta_P} + \sqrt{\delta_Q})$ --- obtained by
1870		applying the error inflation of
1871		Lemma~\ref{lem:restricted-line-mixture-bounds} to the conclusion of
1872		Lemma~\ref{lem:qld-xz-lines} (transported to the sub-line distribution
1873		via Lemma~\ref{lem:qld-sublines}) and to the consistency relations of
1874		Lemma~\ref{lem:qld-4-10} --- the resulting quantity is close to
1875		$\E \sum_{a,b} \bra{\hat\psi}
1876		\hat{M}^{(\mathrm{Point},X),x}_{a}
1877		\hat{M}^{(\mathrm{Point},Z),z}_{b} \ot
1878		\hat{M}^{(\mathrm{Point},Z),z}_{b} \ket{\hat\psi}$,
1879		which, since $\{\hat{M}^{(\mathrm{Point},X),x}_{a}\}$ is a measurement,
1880		equals
1881		$\sum_b \bra{\hat\psi} \hat{M}^{(\mathrm{Point},Z),z}_{b} \ot
1882		\hat{M}^{(\mathrm{Point},Z),z}_{b} \ket{\hat\psi}
1883		\ge 1 - \sqrt{\eps}$
1884		by the self-consistency of the points measurements
1885		(Lemma~\ref{lem:qld-comm-cons}). The deficit is therefore
1886		$O(m(\sqrt{\delta_P} + \sqrt{\delta_Q}) + \sqrt{\eps})$, and taking the
1887		square root gives the claim.
1888	\end{proof}
